function buildResumedBlockResult(entrySteps, stepResults, executionContext, opts) {
  const stepsToCheck = opts?.onlyExecutedSteps ? entrySteps.filter((s) => s.type === "step" && stepResults[s.step.id] !== void 0) : entrySteps;
  const allComplete = stepsToCheck.every((s) => {
    if (s.type === "step") {
      const r = stepResults[s.step.id];
      return r && r.status === "success";
    }
    return true;
  });
  let result;
  if (allComplete) {
    result = {
      status: "success",
      output: entrySteps.reduce((acc, s) => {
        if (s.type === "step") {
          const r = stepResults[s.step.id];
          if (r && r.status === "success") {
            acc[s.step.id] = r.output;
          }
        }
        return acc;
      }, {})
    };
  } else {
    const failedStep = stepsToCheck.find((s) => s.type === "step" && stepResults[s.step.id]?.status === "failed");
    if (failedStep && failedStep.type === "step") {
      const failedResult = stepResults[failedStep.step.id];
      result = {
        status: "failed",
        error: failedResult?.error ?? new Error("Workflow step failed after resume"),
        tripwire: failedResult?.tripwire
      };
    } else {
      const stillSuspended = entrySteps.find((s) => s.type === "step" && stepResults[s.step.id]?.status === "suspended");
      const suspendData = stillSuspended && stillSuspended.type === "step" ? stepResults[stillSuspended.step.id]?.suspendPayload : {};
      result = {
        status: "suspended",
        payload: suspendData,
        suspendPayload: suspendData,
        suspendedAt: Date.now()
      };
    }
  }
  if (result.status === "suspended") {
    entrySteps.forEach((s, stepIndex) => {
      if (s.type === "step" && stepResults[s.step.id]?.status === "suspended") {
        executionContext.suspendedPaths[s.step.id] = [...executionContext.executionPath, stepIndex];
      }
    });
  }
  return result;
}
function getResumeStepPrevOutput({
  isResumedStep,
  stepId,
  stepResults,
  prevOutput
}) {
  if (!isResumedStep) {
    return prevOutput;
  }
  const stepResult = stepResults[stepId];
  return stepResult && Object.prototype.hasOwnProperty.call(stepResult, "payload") ? stepResult.payload : prevOutput;
}
async function persistStepUpdate(engine, params) {
  const {
    workflowId,
    runId,
    resourceId,
    stepResults,
    serializedStepGraph,
    executionContext,
    workflowStatus,
    result,
    error,
    requestContext,
    tracingContext,
    phase
  } = params;
  const operationId = `workflow.${workflowId}.run.${runId}.path.${JSON.stringify(executionContext.executionPath)}.stepUpdate${phase ? `.${phase}` : ""}`;
  await engine.wrapDurableOperation(operationId, async () => {
    const shouldPersistSnapshot = engine.options?.shouldPersistSnapshot?.({ stepResults, workflowStatus });
    if (!shouldPersistSnapshot) {
      return;
    }
    const requestContextObj = engine.serializeRequestContext(requestContext);
    const snapshot = {
      runId,
      status: workflowStatus,
      value: executionContext.state,
      context: stepResults,
      activePaths: executionContext.executionPath,
      stepExecutionPath: executionContext.stepExecutionPath,
      activeStepsPath: executionContext.activeStepsPath,
      serializedStepGraph,
      suspendedPaths: executionContext.suspendedPaths,
      waitingPaths: {},
      resumeLabels: executionContext.resumeLabels,
      result,
      error,
      requestContext: requestContextObj,
      timestamp: Date.now(),
      // Persist tracing context for span continuity on resume
      tracingContext
    };
    const workflowsStore = await engine.mastra?.getStorage()?.getStore("workflows");
    await workflowsStore?.persistWorkflowSnapshot({
      workflowName: workflowId,
      runId,
      resourceId,
      snapshot: engine.options?.pruneSnapshot ? engine.options.pruneSnapshot({ snapshot, workflowStatus }) : snapshot
    });
  });
}
